import{_ as e,o as a,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"Settings Reference","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/settings/index.md","filePath":"user-guide/settings/index.md","lastUpdated":1783494793000}'),n={name:"user-guide/settings/index.md"};function i(d,t,o,l,h,c){return a(),r("div",null,[...t[0]||(t[0]=[s('<h1 id="settings-reference" tabindex="-1">Settings Reference <a class="header-anchor" href="#settings-reference" aria-label="Permalink to &quot;Settings Reference&quot;">​</a></h1><p>A search box sits in the Settings window&#39;s title bar. Type to get a live-filtered popup of matching settings across every section — including the per-plugin entries under Plugins, Hotkeys&#39; Plugin Actions tab, and Startup Panel&#39;s Plugin Tabs sub-tab. Each result shows a breadcrumb (e.g. &quot;Index &gt; Network Drives&quot;) so same-named settings under different tabs stay distinguishable. Selecting a result (click, or Up/Down to highlight and Enter) switches to the right section and tab, scrolls the exact control into view, and briefly flashes a highlight border around it.</p><p>The Settings window has nine sections in its left sidebar:</p><table tabindex="0"><thead><tr><th>Section</th><th>Covers</th></tr></thead><tbody><tr><td><a href="./service-status.html">Service Status</a></td><td>Background service install/start/stop, and the App/Hook/Service log viewer.</td></tr><tr><td><a href="./index-drives.html">Index</a></td><td>Local drives, network drives (incl. WSL distributions), and exclusion rules.</td></tr><tr><td><a href="./general.html">General</a></td><td>Startup behavior, updates, theme, language, search bar layout, and preview window size.</td></tr><tr><td><a href="./hotkeys-page.html">Hotkeys</a></td><td>Global hotkeys, per-plugin action hotkeys, and the process blacklist.</td></tr><tr><td><a href="./plugins.html">Plugins</a></td><td>Installed plugins and per-component enable/disable toggles.</td></tr><tr><td><a href="./favorites.html">Favorites</a></td><td>Custom-named shortcuts to folders, files, and URLs.</td></tr><tr><td><a href="./history.html">History</a></td><td>Search history and quick-window keyword history.</td></tr><tr><td><a href="./startup-panel.html">Startup Panel</a></td><td>The empty-search-box tab strip: Recent Files, Last Directory, and reopening closed plugin tabs.</td></tr><tr><td><a href="./about.html">About</a></td><td>Version info and update checking.</td></tr></tbody></table><p>Each page below documents every option on that section, in order, with its default value and any valid range.</p>',5)])])}const g=e(n,[["render",i]]);export{p as __pageData,g as default};
